    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Votre page de connexion porte votre logo et vos couleurs. Les personnes y saisissent leur mot de passe : elle doit être clairement identifiable comme la vôtre.',
    'your_organization_its_projects_team_keys_and_billing_si_152a2f42' => 'Votre organisation : projets, équipe, clés et facturation. La connexion à vos applications se configure dans la console de chaque environnement.',
    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Un indicateur de fonctionnalité est un réglage que vos applications évaluent pour une personne dans une organisation. Activez-le pour des utilisateurs ou organisations précis, ou un pourcentage de tous les utilisateurs. Chaque application reçoit la même réponse via le claim `feature_flags` du jeton ou le point de terminaison d’évaluation, sans déploiement. Une règle utilisateur prime sur une règle d’organisation, puis sur le déploiement progressif, puis sur la valeur par défaut.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Une clé permet à vos scripts et intégrations d’appeler l’API d’une application en votre nom, sans connexion. Elle ne peut pas faire plus que vous dans cette application. Si vos droits diminuent, ceux de la clé aussi. La clé n’est affichée qu’une fois : copiez-la à sa création et révoquez-la dès qu’elle est divulguée ou inutilisée.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Une permission autorise un rôle à effectuer une action, comme créer des factures ou lire des rapports. Vous pouvez définir vos permissions ici sans code, puis les réunir dans des rôles. Les applications peuvent aussi enregistrer les leurs automatiquement pour refléter les contrôles réellement appliqués. Vous pouvez modifier vos propres permissions ; celles partagées par l’environnement sont utilisables mais non modifiables.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Un téléphone équipé de l’application d’authentification répond aux demandes d’approbation et vous avertit lorsqu’une personne se connecte en votre nom. Enregistrez-le en scannant le code. Supprimez-le immédiatement ici si vous le perdez : il ne pourra plus rien approuver.',
    'a_project_is_one_idp_product_this_organization_owns_and_d87379c8' => 'Un projet est un produit fournisseur d’identité appartenant à cette organisation ; ses environnements y sont rattachés. Tant que l\'organisation n’en crée pas depuis sa propre console, il n’y a rien à sélectionner ou à ouvrir ici. Cet écran ne crée aucun projet à sa place.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Un projet est l’un de vos produits, avec son propre forfait, sa connexion et ses environnements, comme la production et la préproduction. Ouvrez un environnement ici pour l’administrer. Créez un projet lorsque vous lancez un produit qui doit fonctionner et être facturé indépendamment.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Un rôle est une fonction comprise par vos applications, comme rédacteur ou agent d’assistance. Vous attribuez les rôles ici et chaque application définit ce qu’ils permettent. Les rôles suivent la personne dans toutes les applications connectées, pour accorder ou retirer l’accès au même endroit.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Une revue permet de vérifier qui détient quel rôle et s’il reste nécessaire. Les accès s’accumulent quand les personnes changent d’équipe sans perdre leurs anciennes permissions. La revue permet de faire le tri. Les révocations sont appliquées à sa clôture et l’ensemble est consigné pour votre auditeur.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Un schéma décrit les événements d’une action : les types de cibles désignés et les métadonnées attendues. Les événements associés à un schéma sont vérifiés à leur arrivée. Sans schéma, ils sont acceptés tels quels, sauf si le mode strict est activé.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Une organisation est l’espace d’une entreprise inscrite sur cette installation. Il contient ses projets, environnements et équipe. Ouvrez-le pour les administrer. Sa suspension déconnecte ses membres et arrête les connexions dans tous ses environnements.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Les accès s’accumulent. Les personnes changent d’équipe et conservent d’anciens droits jusqu’à ce qu’un auditeur pose la question. Une revue capture les attributions actuelles et exige une décision sur la nécessité de chacune.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Ajoutez la personne à une organisation ci-dessous pour lui donner accès à celle-ci. Si vos applications n’ont pas de séparation par client, attribuez plutôt un rôle d’administration et d’assistance valable dans tout l’environnement.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Un rôle d’administration et d’assistance est attribué à votre personnel, par exemple l’assistance ou l’exploitation, dans tout l’environnement. Il s’applique à chaque organisation sans être visible, attribuable ou révocable par ses administrateurs. Un rôle d’application attribué ainsi reste limité à cette application.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Un rôle d’administration et d’assistance est attribué à votre personnel dans tout l’environnement. Il s’applique à chaque organisation et ses administrateurs ne peuvent ni le voir ni le modifier.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Un agent est un logiciel qui agit dans cet environnement avec une clé de gestion : assistant IA comme Claude Code ou Cursor, robot interne ou service serveur. Donnez à chacun sa propre clé avec les seules portées nécessaires. Choisissez les actions qui attendent votre approbation et révoquez la clé dès que le travail est terminé ou qu’un comportement semble anormal.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'Une API est l’un de vos services qui reçoit des jetons d’accès, comme https://api.example.com. Enregistrez-la avec les portées qu’elle reconnaît. Vous décidez ensuite des portées que les applications enregistrées par les organisations peuvent demander. Un jeton pour cette API contient son adresse comme audience, à vérifier par votre service.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Un environnement est un service d’identité totalement isolé avec ses propres utilisateurs, clés, connexion et émetteur. Tous ceux de cette installation sont listés ici avec leur organisation. Créez un environnement, sélectionnez-le dans la console, puis configurez sa première organisation et son administrateur.',
    'an_environment_is_fully_isolated_its_own_users_keys_sig_bc49f6f9' => 'Un environnement est totalement isolé, avec ses propres utilisateurs, clés, connexion et émetteur. Créez le premier ci-dessus, puis configurez une organisation et un administrateur.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Un fournisseur d’identité qui importe les métadonnées du fournisseur de services utilise cette URL plutôt que l’identifiant d’entité et l’URL ACS séparément. Elle fonctionne avant même de remplir les informations du fournisseur d’identité.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Une organisation regroupe utilisateurs, méthodes de connexion et rôles. Créez-en une ci-dessus ou configurez la première organisation et son administrateur depuis l’écran Environnements.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'Le fournisseur propre à une organisation remplace celui de l’environnement sur sa page de connexion. Les désactivations d’un fournisseur hérité apparaissent aussi. Elles retirent seulement le bouton ; c’est l’obligation de SSO qui interdit les autres méthodes.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'Les clés API et jetons nécessaires à vos applications et agents pour d’autres services sont stockés chiffrés ici plutôt que dans chaque configuration. Déposez un secret une fois et autorisez des applications précises à l’utiliser. Il n’est plus affiché ensuite ; renouvelez-le si vous le perdez.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'Les clés API utilisées par vos applications et agents auprès d’autres services. Chaque valeur est stockée chiffrée, transmise uniquement aux applications autorisées et n’est plus affichée après enregistrement.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Les applications qui demandent à agir au nom de vos utilisateurs. Chaque utilisateur approuve ses propres demandes. Refusez ici uniquement celles qui semblent abusives ; le refus est enregistré dans le journal d’audit.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Les applications qui tiennent leur propre liste d’utilisateurs se désynchronisent dès qu’une personne arrive ou part. Une connexion SCIM transmet chaque changement immédiatement, y compris les départs, souvent oubliés.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID envoie un message signé à votre point de terminaison après un événement, comme une adhésion ou un changement de rôle. Vos systèmes réagissent sans interrogation régulière. Les livraisons sont retentées si nécessaire. L’information arrive après l’événement : le destinataire ne peut pas intervenir dans la décision.',
    'certify_what_is_still_needed_revoke_what_is_not_nothing_31e57691' => 'Confirmez les accès encore nécessaires et révoquez les autres. Rien ne prend effet avant la clôture. Un rôle d’administration et d’assistance révoqué est alors retiré dans toutes les organisations à la fois.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Choisissez SCIM si votre fournisseur nous envoie les données, Google Workspace ou Entra si nous devons les récupérer, ou votre système RH, comme Workday, BambooHR, Rippling, HiBob ou Personio, pour créer les comptes à la date d’arrivée.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code ouvre votre navigateur pour vous connecter ici et vous demande quoi autoriser. Aucune clé à conserver. Tout client MCP utilisant OAuth fonctionne de la même façon avec cette URL.',
    'comma_or_space_separated_a_scope_you_type_is_unowned_it_c5513416' => 'Séparez les valeurs par des virgules ou des espaces. Une portée saisie n’a pas d’API propriétaire et apparaît telle quelle dans les jetons de l’application. Elle ne peut jamais désigner l’audience d’une API enregistrée ; utilisez les listes ci-dessus pour cela.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Créer, modifier, activer, désactiver et supprimer les connexions SSO, imposer le SSO à une organisation, vérifier ses domaines de messagerie et activer leur routage SSO. Modifie la façon dont les personnes se connectent.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Crée l’organisation, son propriétaire, son premier produit et l’environnement de production de ce produit. Le propriétaire reçoit par e-mail un lien pour définir son mot de passe ; vous n’en choisissez pas à sa place.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Définir, remplacer et supprimer les schémas de validation des événements d’audit, et modifier leur durée de conservation. Une durée plus courte supprime définitivement les événements plus anciens.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Supprimer cette organisation supprime tous ses projets et environnements. Pour protéger les fournisseurs d’identité actifs, cette opération n’est pas en libre-service. Contactez l’assistance pour continuer.',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Chaque organisation est une entreprise ou une équipe utilisant votre produit, avec ses propres membres, rôles, domaines et SSO. Créez-en une par entreprise inscrite. Ouvrez-la pour gérer membres, invitations et domaines vérifiés, ou pour la suspendre.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Chaque pipeline permet aux personnes de connecter leur propre compte chez un service comme GitHub, Google ou Slack. Les jetons sont stockés chiffrés et renouvelés ici. Les applications autorisées demandent un jeton valide lorsqu’elles appellent le service au nom de la personne, sans en stocker elles-mêmes.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Chaque projet de votre organisation a son propre forfait et quota d’environnements. Ils apparaissent avec l’utilisation du mois : organisations, connexions SSO facturées et connexions utilisateur. Le tarif prend en compte les utilisateurs actifs mensuels et les connexions d’entreprise comme SSO et SCIM. Les environnements de test n’entraînent pas de frais de connexion.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Tout l’environnement : toute personne ayant un compte dans cet environnement peut se connecter à l’application, quelle que soit son organisation. Désignez une organisation si ce n’est pas votre intention.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Effacer définitivement une personne (RGPD, art. 17) : ses identifiants, sessions, appartenances et données personnelles sont supprimés et son compte pseudonymisé. Irréversible.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Ordre d’évaluation : liste de refus, liste d’autorisation, vos règles de haut en bas avec décision à la première correspondance, puis règles intégrées avec décision de la plus stricte qui correspond. Sans correspondance, l’accès est autorisé.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Chaque action est acceptée telle qu’envoyée par l’application. Ajoutez un schéma pour vérifier ses événements à l’arrivée. La cohérence du journal se garantit à l’écriture, pas au moment de la lecture.',
    'every_administrative_change_members_roles_connections_a_ef641619' => 'Toute modification administrative concernant les membres, rôles, connexions ou applications est enregistrée ici dès qu’elle survient, avec son auteur et sa date. Aucune configuration n’est nécessaire.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Les clés API placées dans les configurations ou fichiers d’environnement ne se renouvellent pas centralement et sont difficiles à retirer rapidement. Ici, elles sont chiffrées, attribuées par application et révocables en un clic.',
    'every_api_key_the_people_in_this_organization_have_crea_b802c1e7' => 'Toutes les clés API créées par les personnes de cette organisation pour ses applications. Révoquez celles qui sont divulguées ou inutilisées. Chaque personne crée ses clés dans Mon compte.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Toutes les clés API créées par les personnes de cette organisation : détenteur, application, permissions et dernière utilisation. Une clé n’a pas plus de droits que son détenteur et cesse de fonctionner à son départ. Révoquez les clés divulguées ou inutilisées. Chacun crée les siennes dans Mon compte.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Chaque application qui connecte des personnes via Cbox ID ou appelle son API est enregistrée ici et reçoit ses propres identifiants. Enregistrez-en une par application et par environnement. Ne partagez jamais les identifiants pour pouvoir en révoquer un sans affecter les autres.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Tous les navigateurs et appareils connectés à votre compte, les applications autorisées à agir pour vous et vos dernières connexions et modifications de sécurité. Si un élément vous est inconnu, fermez la session ou retirez l’accès de l’application, puis changez votre mot de passe.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Chaque modification dans cette organisation : qui a fait quoi, sur quel élément et quand. Les empreintes des entrées sont chaînées ; toute suppression ou modification rompt la chaîne et devient détectable. Ce journal est volontairement en lecture seule : c’est le document remis à l’auditeur.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Toutes les connexions entre Cbox ID et d’autres systèmes au même endroit : SSO, connexion sociale, synchronisation d’annuaires et RH, provisionnement sortant, applications SAML, webhooks, hooks, flux de journaux et pipelines. Chaque carte du catalogue ouvre sa page de configuration. Connexions liste les connexions existantes avec leur état, les erreurs en premier.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Toutes les organisations de l’environnement sélectionné dans la console, sous forme d’arbre de revendeurs, d’organisations gérées et de sous-unités. Créez ou suspendez une organisation, ou déplacez-la sous une autre organisation parente.',
    'every_page_you_open_from_now_on_organizations_usage_org_7ba726d3' => 'Toutes les pages ouvertes désormais, comme Organisations, Utilisation ou le détail d’une organisation, liront cet environnement. Aucun des deux environnements n’est modifié.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Toutes les personnes ayant une identité dans cet environnement, quelles que soient leurs organisations. Ouvrez une personne pour réinitialiser mot de passe ou second facteur, fermer ses sessions, la désactiver, modifier ses organisations et rôles, ou l’effacer définitivement à sa demande.',
    'every_revoke_recorded_on_this_review_is_applied_for_rea_1abdd266' => 'Toutes les révocations enregistrées dans cette revue sont appliquées maintenant. Les éléments non examinés suivent sa politique, qui prévoit une révocation par défaut. Cette action est irréversible.',
    'every_secret_that_signs_this_app_in_right_now_only_a_ha_6aceec1d' => 'Tous les secrets actuellement utilisables par cette application. Seule une empreinte de chacun est stockée. La liste montre les quatre derniers caractères pour identifier celui utilisé par un déploiement.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Tous les jetons qu’il a émis sont révoqués et aucune nouvelle connexion ne peut l’utiliser. Une application qui vérifie elle-même les jetons les accepte jusqu’à leur expiration, au plus tard à la fin de la session.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Toutes les méthodes de connexion avec leur état et l’endroit où les modifier : mot de passe, clés d’accès, lien par e-mail, connexion sociale, Enterprise SSO et second facteur. L’environnement contrôle la plupart ; chaque organisation gère ses connexions SSO. Les restrictions du déploiement sont indiquées avec le nom du réglage concerné.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Tous les organisations de cette installation. Ouvrez-en un pour gérer ses produits et environnements. Le suspendre déconnecte ses membres et arrête l’authentification dans tous ses environnements.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Toutes les personnes qui administrent cette organisation, leur rôle intégré (Propriétaire, Administrateur, Développeur, Membre ou Lecteur) et leurs environnements accessibles. Invitez par e-mail et donnez uniquement les environnements nécessaires au travail de chacun.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Toutes les personnes pouvant se connecter à cette organisation et vos invitations non encore acceptées. Invitez par e-mail : les personnes configurent leur propre connexion, sans que vous ayez à manipuler leurs mots de passe.',
    'platform_search_summary' => 'Résultats pour « :term » : organisations : :organizations ; utilisateurs : :users.',
