    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Un code peut être volé par détournement de carte SIM ou portage frauduleux du numéro, intercepté dans le réseau téléphonique ou saisi sur une fausse page de connexion convaincante. Il reste bien plus sûr qu’un mot de passe seul. Activez-le pour les personnes qui ne peuvent pas utiliser d’application d’authentification ou de clé d’accès.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 Un logo chargé depuis un autre site révélait à ce site qui ouvrait votre page de connexion. Les pages hébergées n’affichent donc désormais que les images importées ici. Importez-le sous :part2 ci-dessous ou supprimez-le pour faire disparaître cet avis.',
    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 Un rôle est un libellé inscrit dans le jeton. Ceux déclarés par une application sont en lecture seule ici ; vous définissez les autres. Chaque membre possède aussi exactement un :part2 :part3 :part4 (propriétaire, administrateur, développeur, membre ou lecteur), qui détermine ce qu’il peut administrer dans cette console.',
    '_part1_already_belongs_to_another_api_in_this_environme_bab95da8' => '« :part1 » appartient déjà à une autre API dans cet environnement. Une demande de jeton désigne une portée uniquement par sa clé ; chaque clé ne peut donc appartenir qu’à une seule API.',
    '_part1_belong_to_an_api_this_app_may_not_use_they_are_l_99264721' => ':part1 appartiennent à une API que cette application ne peut pas utiliser. Ces portées sont exclues de tous les jetons ; supprimez-les des portées saisies.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 peuvent se connecter par mot de passe ou avec cette connexion. Imposer l’authentification unique refuse toutes les autres méthodes, afin que même les accès déjà délivrés ne puissent pas contourner le fournisseur que vous venez de configurer. La plupart des entreprises qui connectent un IdP souhaitent ce comportement, mais lisez d’abord ses conséquences.',
    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => ':part1 n’a pas encore de permissions, donc :part2 :part3 est vide. Le nom du rôle reste disponible et peut être utilisé.:part4',
    '_part1_is_already_set_up_for_this_organization_change_i_dea89857' => ':part1 est déjà configuré pour cette organisation. Modifiez ses identifiants ou supprimez d’abord la connexion.',
    '_part1_is_no_longer_offered_anyone_who_signed_in_with_i_b1a43020' => ':part1 n’est plus proposé. Les personnes qui l’ont utilisé conservent leur compte et peuvent toujours utiliser leur mot de passe.',
    '_part1_is_off_on_every_sign_in_page_its_credentials_are_2dc58cfc' => ':part1 est désactivé sur toutes les pages de connexion. Ses identifiants sont conservés pour vous permettre de le réactiver.',
    '_part1_is_off_on_this_organization_s_sign_in_page_its_c_5a7d1345' => ':part1 est désactivé sur la page de connexion de cette organisation. Ses identifiants sont conservés pour vous permettre de le réactiver.',
    '_part1_is_your_only_way_to_sign_in_set_a_password_or_ad_968a0fd3' => ':part1 est votre seul moyen de connexion. Définissez un mot de passe ou ajoutez une clé d’accès avant de le déconnecter.',
    '_part1_is_your_organization_s_single_sign_on_it_is_how_a02887f1' => ':part1 est la connexion unique de votre organisation. Elle permet à votre organisation de vous identifier et ne peut donc pas être déconnectée ici.',
    '_part1_its_team_is_administered_under_organization_team_6abad4af' => ':part1 Son équipe est administrée sous Organisation › Équipe par une personne détenant un rôle dans l\'organisation, et non depuis cette page.',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 Rien ici n’est encore défini par :part3. Toute modification ci-dessous devient une règle propre à cette organisation.',
    '_part1_part2_up_to_date_part3_deprovisioned_part4_part5_5604a19e' => ':part1 :part2 à jour, :part3 déprovisionnés,:part4 :part5 ignorés, :part6 groupes :part7.',
    '_part1_part2_update_your_receiver_first_from_the_next_a_d1d60a6e' => ':part1 :part2 Mettez d’abord votre récepteur à jour : dès la prochaine tentative, il refusera toute livraison qu’il ne peut pas vérifier.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 refuse la connexion si cette valeur ne correspond pas exactement. Elle est conservée pour cette configuration : vous pouvez la coller dans :part2 maintenant, puis enregistrer ici.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 — les sessions, clés d’accès et seconds facteurs, profils chez les fournisseurs d’identité, données d’annuaire, jetons émis, attributions de rôles et historique d’audit sont conservés et peuvent être réactivés.',
    'the_metadata_value_for_part1_must_be_text_63748730' => 'La valeur de métadonnée pour [:part1] doit être du texte.',
    'the_new_key_for_part1_copy_it_now_you_won_t_be_able_to_42e3ecb3' => 'La nouvelle clé pour :part1. Copiez-la maintenant, elle ne sera plus affichée.',
    'the_newest_entries_on_part1_s_trail_dac97d7d' => 'Les dernières entrées de l’historique de :part1.',
    'the_people_in_part1_cf74b32e' => 'Les personnes dans :part1.',
    'the_people_on_part1_and_what_each_may_reach_474ab0a4' => 'Les personnes dans :part1 et les accès de chacune.',
    'the_role_part1_belongs_to_one_organization_and_cannot_b_e2bba059' => 'Le rôle [:part1] appartient à une organisation et ne peut pas être attribué partout.',
    'the_same_code_step_by_step_with_sign_out_part1_part2_4d2f071e' => 'Le même code, étape par étape, avec la déconnexion ::part1 :part2 .',
    'the_scim_base_url_must_be_a_public_address_part1_4cfd762c' => 'L’URL de base SCIM doit être une adresse publique. (:part1)',
    'the_secret_was_shown_once_when_the_app_was_created_part_7a1fcce3' => 'Le secret a été affiché une seule fois, lors de la création de l’application.:part1 :part2 :part3 pour en obtenir un nouveau.',
    'the_whole_environment_part1_6c96bfa7' => 'L’environnement entier :part1',
    'theme_this_organization_s_sign_in_page_its_team_signs_i_cceda878' => 'Personnalisez la page de connexion de cette organisation. Son équipe se connecte sur :part1 :part2 .',
    'these_apply_to_every_organization_in_part1_not_only_par_ac56590d' => 'Ces paramètres s’appliquent à toutes les organisations dans :part1, pas seulement à :part2 .',
    'these_are_its_own_credentials_for_that_environment_s_co_a68e7d01' => 'Ce sont ses propres identifiants, pour la configuration de cet environnement. :part1',
    'this_will_allow_part1_to_6ac64554' => 'Cela permettra à :part1 de',
    'this_will_sign_people_out_of_part1_c2cac70c' => 'Cela déconnectera les personnes de :part1',
    'to_answer_a_right_to_erasure_request_use_part1_at_the_f_536cbf09' => 'Pour répondre à une demande d’effacement, utilisez plutôt :part1 au bas de cette page.',
    'turn_off_part1_cdd28418' => 'Désactiver :part1',
    'turn_off_part1_on_this_page_e3c91b07' => 'Désactiver :part1 sur cette page',
    'turn_on_part1_41acb93f' => 'Activer :part1',
    'turn_on_part1_for_everyone_ef925d74' => 'Activer :part1 pour tout le monde',
    'two_factor_authentication_part1_8c022f7b' => 'Authentification à deux facteurs :part1',
    'two_factor_part1_part2_d0a29caf' => 'Deux facteurs : :part1. :part2',
    'type_part1_to_confirm_25ad7324' => 'Saisissez :part1 pour confirmer',
    'unchanged_by_anything_here_so_nothing_to_update_in_part_75ac8c0d' => 'Les modifications ici n’y changent rien ; aucune mise à jour n’est nécessaire dans :part1.',
    'until_part1_ca03d4b6' => 'jusqu’à :part1',
    'updated_part1_275f47a3' => 'Mis à jour :part1',
    'use_your_environment_s_defaults_for_part1_c214943d' => 'Utiliser les paramètres par défaut de votre environnement pour :part1 ?',
    'user_created_a_sign_in_link_is_on_its_way_to_part1_340287fa' => 'Utilisateur créé. Un lien de connexion est en cours d’envoi à :part1.',
    'verification_email_sent_to_part1_254c8e75' => 'E-mail de vérification envoyé à :part1.',
    'verify_part1_5e0158de' => 'Vérifier :part1',
    'via_part1_b3f55fad' => 'via :part1',
    'view_part1_ac7c77ab' => 'Voir :part1',
    'wants_to_act_on_behalf_of_part1_5e98fe61' => 'souhaite agir au nom de :part1',
    'we_could_not_reach_part1_at_part2_check_the_details_par_c1087a18' => 'Impossible de joindre :part1 à l’adresse :part2. Vérifiez les informations. (:part3)',
    'webhook_delivered_at' => ' · livré :time',
    'webhook_retry_at' => ' · nouvelle tentative :time',
    'welcome_back_part1_3c339e48' => 'Bon retour, :part1',
    'what_an_app_may_be_allowed_to_do_at_this_api_only_part1_c0ec6f18' => 'Ce qu’une application peut être autorisée à faire sur cette API. Seules les applications propres à :part1 peuvent détenir ces permissions.',
    'what_is_part1_00d3f3e7' => 'Qu’est-ce que :part1 ?',
    'what_you_are_administering_and_the_details_your_apps_ne_23bc71ef' => 'Ce que vous administrez et les informations nécessaires à l’intégration de vos applications. :part1',
    'withdraw_access_for_part1_10961483' => 'Révoquer l’accès de l’application :part1',
    'withdraw_the_invitation_to_part1_13c82934' => 'Retirer l’invitation à :part1',
    'withdraw_the_invitation_to_part1_fafedcae' => 'Retirer l’invitation à :part1 ?',
    'you_can_also_part1_part2_part3_53f32513' => 'Vous pouvez aussi :part1 :part2 .:part3',
    'you_can_turn_it_off_again_on_part1_part2_sessions_that_89d71a9d' => 'Vous pouvez le désactiver à nouveau sur :part1 :part2 ; les sessions terminées le restent.',
    'you_hold_no_permissions_in_part1_so_a_key_would_identif_2c680207' => 'Vous n’avez aucune permission dans :part1. Une clé ne ferait donc que vous y identifier.',
    'your_endpoint_verifies_the_part1_header_on_each_request_b7ca1bb8' => 'Votre point de terminaison vérifie l’en-tête :part1 de chaque requête avec ce secret.',
    'your_roles_using_permission' => 'Dans :count de vos rôles|Dans :count de vos rôles',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Tout ce que votre organisation a configuré et ce qu’il reste à faire. La liste de contrôle reflète l’état réel de la configuration : chaque étape est cochée automatiquement dès qu’elle est terminée.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Toute votre identité visuelle sur une seule page : logo, favicon, couleurs, police et coins de la page de connexion hébergée, avec aperçu en direct, ainsi que le nom du produit, l’expéditeur des e-mails et le message de bienvenue. Configurez-les une seule fois pour tout l’environnement ; chaque organisation en héritera. Vous pouvez aussi personnaliser une organisation dans son onglet Identité visuelle.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Dès la prochaine tentative, les blocages refusent les connexions et les inscriptions dans cet environnement, et les contrôles exigent une vérification supplémentaire. Une règle incorrecte peut empêcher de vraies personnes d’accéder au service.',
    'grant_one_to_the_people_who_support_or_run_your_apps_an_3991d001' => 'Accordez-en un aux personnes qui prennent en charge ou exécutent vos applications. Le propre rôle d’une application atteint uniquement les jetons de cette application ; un rôle pour toutes les applications atteint chacune d\'entre elles.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Le nombre d’organisations, d’utilisateurs, de connexions SSO, d’applications et de synchronisations d’utilisateurs dans cet environnement, avec un lien vers chaque page correspondante. Les raccourcis en dessous permettent de créer les éléments les plus courants : une organisation, un utilisateur, une connexion SSO ou une application.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Le nombre de personnes connectées et la fréquence des appels de vos applications à l’API au cours des 30 derniers jours. Cette vue vous aide à évaluer la charge et à repérer les anomalies. Ce n’est pas une facture.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'La fréquence de récupération des données et les champs du système RH à copier pour chaque personne, par exemple le centre de coûts ou le site. Après modification des champs, la prochaine synchronisation sera complète.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Comment les données d’audit sont exportées de Cbox ID : une exportation planifiée envoie les nouvelles entrées à votre SIEM ou à vos archives toutes les cinq minutes. Une tâche quotidienne de conservation crée un point de contrôle du journal sans rien supprimer. Vous pouvez ici récupérer l’historique d’audit d’une personne pour répondre à une demande d’accès au titre du RGPD ou vérifier, dans la console d’un environnement, que les exportations fonctionnent.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Si l’application déclare ensuite une autre URL, cette approbation est annulée et vous devrez la donner à nouveau. Le destinataire des mots de passe ne doit pas changer sans votre accord. La connexion déléguée accompagne la transition : lorsqu’il ne reste plus que quelques personnes sur l’ancien système, désactivez-la et envoyez-leur un lien de réinitialisation du mot de passe.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Le bouton disparaît et les identifiants sont supprimés. Les personnes qui ont utilisé cette connexion conservent leur compte et peuvent toujours utiliser leur mot de passe. Pour conserver les identifiants, désactivez plutôt la connexion.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'Ses portées sont également supprimées. Les applications qui les détenaient les conservent comme portées saisies, sans accès à cette API. Les jetons déjà émis continuent de fonctionner jusqu’à leur expiration.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Clés de l’API de gestion d’un environnement : gérez ses organisations, membres, invitations, rôles et applications depuis votre propre backend. Chaque clé possède des portées explicitement définies.',
    'keys_this_organization_s_people_have_created_for_its_ap_9d7e0611' => 'Les clés créées par les utilisateurs de cette organisation pour ses applications, avec les permissions de chacune. Les utilisateurs créent leurs propres clés. Révoquez celles qui ont fuité ou ne sont plus utilisées.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Laissez ce champ vide pour presque tous les fournisseurs : leurs jetons d’identité sont vérifiés à l’aide des clés de signature publiées dans leur document de découverte (jwks_uri), y compris après rotation. Collez la clé publique PEM du fournisseur uniquement s’il ne publie aucune clé.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Permettez aux utilisateurs de se connecter avec un compte existant. Configurez un fournisseur une fois pour l’environnement et toutes les organisations le proposeront. Une organisation peut utiliser ses propres identifiants à la place ou désactiver un fournisseur.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Permettez aux utilisateurs de vos applications de connecter leur propre compte GitHub, Google, Slack ou Salesforce pour que vos applications appellent ces API en leur nom. Leurs jetons sont stockés sous forme chiffrée, renouvelés ici et mis temporairement à disposition des seules applications que vous autorisez.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Permet à vos utilisateurs de se connecter avec leur compte d’entreprise existant chez Microsoft Entra ID, Okta ou Google Workspace plutôt qu’avec un mot de passe distinct ici. Connectez votre fournisseur d’identité et vérifiez vos domaines de messagerie une seule fois. Toutes les personnes utilisant ces domaines seront ensuite dirigées vers votre fournisseur pour se connecter.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'La connexion avec Entra ID, Okta ou Google Workspace est disponible dans l’offre Enterprise. Contactez votre équipe commerciale pour l’activer pour cette organisation.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Les liens encore valides remis à l’administrateur informatique de cette organisation. Un lien révoqué cesse immédiatement de fonctionner. Les configurations déjà effectuées par son intermédiaire sont conservées.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Recherche une organisation par son nom ou son identifiant court, ou un utilisateur par son nom ou son adresse e-mail, dans tous les environnements de cette installation, pas seulement dans celui ouvert dans la console. Utilisez cette recherche lorsqu’une personne demande de l’aide et que vous ignorez son environnement.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Les schémas de métadonnées utilisent un sous-ensemble de JSON Schema : un objet dont les propriétés sont des chaînes, nombres, entiers, booléens ou valeurs null, avec des règles de valeurs autorisées, longueur, plage, motif et format. Enregistrer une modification crée une nouvelle version. Les événements déjà enregistrés conservent la version utilisée pour leur validation.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Transmet chaque nouvelle entrée du journal d’audit aux outils de votre équipe de sécurité, comme un SIEM, dès son écriture. Configurez ce flux pour commencer les investigations dans les outils habituels de l’équipe, sans demander d’abord une exportation. La livraison est garantie au moins une fois ; des doublons occasionnels sont donc possibles.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Pour la plupart des intégrations, les webhooks sont plus adaptés : ils s’exécutent après l’événement et ne peuvent pas bloquer son déroulement. Utilisez un hook uniquement si votre système doit intervenir pendant une connexion ou l’émission d’un jeton.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Aucun nouveau secret n’est émis. Dès la prochaine tentative, y compris les nouvelles tentatives, les livraisons utiliseront les en-têtes de l’autre méthode. Un récepteur qui n’a pas été mis à jour les refusera toutes.',
    'nobody_is_on_this_organization_it_has_no_owner_so_nobod_0a51d66d' => 'Cette organisation n’a ni membre ni propriétaire ; personne ne peut donc se connecter pour l’administrer. Il s’agit d’un échec de provisionnement à examiner, pas simplement d’une liste vide.',
    'nothing_is_always_refused_and_nothing_skips_the_rules_d_6699d9d9' => 'Aucune entrée n’est systématiquement refusée ou exemptée des règles. Bloquez une plage d’adresses à l’origine d’attaques ou exemptez le réseau de vos bureaux des règles de fréquence de connexion.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Affiche Google, GitHub, Apple et d’autres fournisseurs sur votre page de connexion pour les personnes qui préfèrent un compte existant à un nouveau mot de passe. Configurez un fournisseur une fois pour l’environnement et toutes les organisations le proposeront. Une organisation peut utiliser ses propres identifiants ou désactiver un fournisseur. Vous fournissez les identifiants ; le reste est rempli automatiquement. Une adresse e-mail transmise par un fournisseur ne suffit jamais à elle seule pour accéder à un compte existant ici.',
    'on_for_this_percentage_of_everyone_the_rules_above_do_n_6ca1e886' => 'Activé pour ce pourcentage des personnes auxquelles les règles ci-dessus ne s’appliquent pas. Un hachage stable de l’identifiant utilisateur sélectionne toujours les mêmes personnes ; augmenter le pourcentage ne fait qu’en ajouter. Laissez vide pour ne pas effectuer de déploiement progressif.',
    'one_marked_event_siem_stream_test_sent_now_with_this_st_c0cf0c4a' => 'Un événement marqué (siem.stream.test) est envoyé maintenant avec les paramètres et identifiants de ce flux, sans mise en file d’attente ni nouvelle tentative. Un succès efface aussi la mention « Action requise ».',
    'one_per_line_including_the_scheme_https_app_example_com_71de2531' => 'Une entrée par ligne, avec le protocole, par exemple https://app.example.com. Si une ligne est invalide, toute la liste est refusée. Les lignes incorrectes ne sont pas supprimées silencieusement.',
    'one_type_per_resource_type_its_relation_s_below_it_a_re_18943de8' => 'Un `type` par type de ressource, avec ses entrées `relation` en dessous. Une relation est déterminée par les sujets désignés directement dans un tuple ([user, group#member]), une autre relation (owner), une relation sur un parent (viewer from parent) ou une combinaison avec or, and ou but not.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Une organisation de cette installation, avec son équipe, ses projets et tous les environnements de ces projets. Le suspendre déconnecte ses membres et arrête l’authentification dans tous ces environnements.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Uniquement pour un fournisseur qui ne publie pas ses clés de signature (jwks_uri) dans son document de découverte. Sinon, les clés y sont récupérées, y compris après rotation. Saisissez une clé publique PEM. Elle est stockée sous forme chiffrée et ne sera plus affichée. Laissez vide pour conserver la clé actuelle.',
    'only_the_active_members_of_the_organization_you_choose_a4a82dec' => 'Seuls les membres actifs de l’organisation choisie peuvent se connecter à cette application. Tous les autres sont refusés, et le refus est enregistré dans le journal d’audit.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Les détails de l’organisation dans l’environnement cible : membres, SSO, domaines, droits attribués et activité récente. Seul le statut de l’organisation peut être modifié sur cette page.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Les organisations, utilisateurs et sessions actives de tous les environnements de cette installation, ainsi que les organisations comptant le plus de membres. Cette vue ne fait que lire les données et ne change jamais l’environnement sélectionné dans la console.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Choisissez votre framework : une application est créée avec une redirection vers votre serveur de développement local, les variables d’environnement à copier et le code de connexion. La page attend qu’une personne se connecte réellement. En dessous figurent les étapes pour en faire un produit : identité visuelle, organisations, SSO, agent, collègue et mise en production. Chaque étape est cochée automatiquement selon l’état réel de l’environnement, jamais manuellement.',
    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Les opérateurs de plateforme administrent tous les organisations et environnements de cette installation à un niveau supérieur. N’ajoutez comme opérateur qu’une personne responsable de l’installation elle-même et suspendez son accès dès que ce n’est plus sa fonction.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Connectez un fournisseur d’identité à notre point de terminaison SCIM, connectez Google Workspace ou Microsoft Entra, ou reliez votre système RH : Workday, BambooHR, Rippling, HiBob ou Personio. Nous récupérerons les données de vos utilisateurs dans les systèmes connectés selon un calendrier.',
    'prove_which_email_domains_your_organization_owns_a_veri_a1717fad' => 'Vérifiez les domaines de messagerie que possède votre organisation. Un domaine vérifié peut diriger toutes les personnes ayant une adresse sur ce domaine directement vers votre connexion SSO d’entreprise.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar évalue chaque connexion et inscription : essais d’identifiants volés, vitesse caractéristique d’un bot, déplacements géographiquement impossibles, nouveaux appareils, réseaux anonymisants et adresses jetables, ainsi que vos propres règles et listes d’autorisation ou de blocage. Chaque décision est enregistrée. Une fois le mode d’application activé, Radar bloque l’accès ou demande un second facteur. Examinez les décisions ici avant de l’activer et lorsqu’une personne signale un problème de connexion.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar évalue chaque connexion et inscription : essais d’identifiants volés, vitesse caractéristique d’un bot, déplacements géographiquement impossibles, nouveaux appareils, réseaux anonymisants et adresses jetables, ainsi que vos propres règles et listes. Les motifs de chaque décision sont enregistrés.',
    'refuse_passwords_found_in_known_data_breaches_checked_a_db4c6959' => 'Refuser les mots de passe présents dans des fuites de données connues. La vérification utilise Have I Been Pwned sans jamais envoyer le mot de passe. Si le service est inaccessible, l’inscription est autorisée plutôt que bloquée.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Enregistre les applications qui acceptent cet environnement comme fournisseur d’identité SAML. Leurs utilisateurs se connectent avec les comptes qu’ils possèdent déjà ici. Associez chaque application à son organisation pour limiter l’accès à ses membres. Sans association, elle est ouverte à tous les utilisateurs de l’environnement. Il s’agit du sens sortant. Pour permettre la connexion avec un compte d’entreprise externe, utilisez le SSO d’entreprise sous Authentification.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Les demandes apparaissent automatiquement ici lorsqu’une application ou un agent a besoin de votre approbation pour agir en votre nom. Vous n’avez rien à faire en attendant. Refusez toute demande que vous n’avez pas initiée.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Les demandes d’agents souhaitant agir au nom d’un utilisateur apparaissent ici dès leur arrivée. Chaque utilisateur approuve ses propres demandes. Cette page permet de refuser une demande qui semble abusive.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Actuellement, les utilisateurs se connectent avec des identifiants conservés ici. Connectez votre fournisseur pour qu’ils utilisent leur compte d’entreprise existant. Ils perdront l’accès ici dès que vous désactiverez leur compte chez ce fournisseur.',
    'scopes_sign_out_uris_token_settings_and_the_roles_manif_c736e69a' => 'Les portées, URI de déconnexion, paramètres des jetons et URL du manifeste des rôles sont copiés tels quels. Les secrets, clés et utilisateurs de l’application ne sont pas copiés : ils appartiennent à l’environnement dans lequel ils ont été créés.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Voyez l’application exactement comme l’un de ses utilisateurs : vous vous connectez en son nom, pour le motif indiqué et pendant une heure au maximum. L’application connaît votre véritable identité et ne reçoit aucun moyen de prolonger la connexion. Le journal d’audit de l’organisation enregistre qui l’a fait et pourquoi.',
    'send_this_single_use_link_to_whoever_configures_your_id_e8056999' => 'Envoyez ce lien à usage unique à la personne qui configure votre fournisseur d’identité. Il expire bientôt et fonctionne sans compte. Copiez-le maintenant : il n’est affiché qu’une seule fois.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Envoyez ce lien à usage unique à la personne qui gère le fournisseur d’identité de l’organisation, si elle ne l’a pas déjà reçu par e-mail. Il fonctionne sans compte jusqu’à son expiration. Copiez-le maintenant : il n’est affiché qu’une seule fois.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Expose les points de terminaison d’identité d’un environnement sur votre propre domaine, par exemple login.example.com, plutôt que sur le nôtre. Vous prouvez la propriété du domaine avec un enregistrement DNS TXT. Configurez-le si les utilisateurs doivent uniquement voir votre adresse lors de la connexion.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Définissez ceci comme politique de confiance du rôle (IAM › Roles › Trust relationships). La plateforme ne peut assumer le rôle qu’en présentant l’identifiant externe de ce flux. Ainsi, personne d’autre sur cette plateforme ne peut diriger un flux vers votre rôle.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Les connexions et requêtes que Cbox ID a jugées assez risquées pour les signaler, les plus récentes d’abord, avec le score et ses motifs. Consultez cette vue après une hausse des échecs de connexion ou lorsqu’une personne signale une connexion qu’elle n’a pas effectuée.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Les connexions, jetons émis, nouveaux utilisateurs et activations de l’authentification à deux facteurs, jour par jour sur les 30 derniers jours, sauf si une autre période est configurée. La page reste vide tant que le responsable de l’installation n’a pas configuré le stockage des données d’analyse.',
    'snapshots_every_admin_support_role_each_role_held_acros_351f6f6d' => 'Prend un instantané de tous les rôles d’administration et d’assistance détenus dans l’environnement, sous forme d’éléments à certifier ou à révoquer. Une révocation retire le rôle dans toutes les organisations à la fois.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Les logiciels qui agissent dans cet environnement avec une clé de gestion : Claude Code, Cursor, un bot interne ou votre propre backend. Chacun ne dispose que des portées que vous lui avez attribuées et attend votre approbation pour les actions que vous avez choisies.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Certains rôles ne doivent jamais être attribués à la même personne : celle qui crée un paiement ne devrait pas aussi l’approuver. Définissez ces paires ici. Cbox ID bloque les nouvelles attributions contraires à cette règle et montre les personnes qui possèdent déjà les deux rôles.',
    'splunk_elastic_graylog_cef_and_generic_json_are_http_co_8d405816' => 'Splunk, Elastic, Graylog, CEF et Generic JSON sont des collecteurs HTTP pour lesquels vous indiquez une URL. Datadog, Amazon S3 et Google Cloud Storage utilisent leurs propres paramètres.',
    'start_from_the_documents_in_folders_example_owners_edit_ca2a0af5' => 'Partez de l’exemple des documents dans des dossiers : propriétaires, éditeurs et lecteurs, avec des droits d’accès au dossier hérités par tout son contenu. Les tuples et les contrôles de permission nécessitent d’abord un schéma.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Des options que vos applications interrogent pour une personne dans une organisation. Activez une fonctionnalité pour des utilisateurs ou organisations précis, ou pour une proportion de tous les utilisateurs. Chaque application reçoit la même réponse, dans le jeton ou via l’API.',
    'the_address_tokens_for_this_api_name_as_their_audience_cdea85aa' => 'L’adresse que les jetons destinés à cette API indiquent comme destinataire et que votre API vérifie. Elle ne pourra pas être modifiée ensuite, car tous les jetons déjà émis la contiennent.',
    'the_agent_is_refused_and_cannot_act_on_this_person_s_be_e1cd49d2' => 'La demande de l’agent est refusée et il ne peut pas agir au nom de cette personne. Le refus est enregistré dans le journal d’audit et ne peut pas être annulé. L’agent doit présenter une nouvelle demande.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Les événements d’audit envoyés par votre application pour chaque organisation qu’elle sert : qui a fait quoi dans votre produit, et quand. Ils sont conservés dans une chaîne de hachage propre à chaque organisation et affichés à ses administrateurs. Utilisez cette fonction lorsqu’une organisation demande le journal d’audit de son compte. Définissez des schémas pour garder les événements cohérents.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Les événements d’audit envoyés par votre application pour toutes les organisations qu’elle sert, les plus récents d’abord. Les événements de chaque organisation forment leur propre chaîne de hachage.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'Le journal d’audit est ici, tandis que les outils de votre équipe de sécurité sont ailleurs. Un flux leur transmet chaque nouvelle entrée dès son écriture, pour qu’une investigation ne commence pas par une demande d’exportation CSV.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Le bouton disparaît de la page de connexion de cette organisation. Le fournisseur propre à l’environnement ne le remplace pas. Les identifiants sont conservés pour permettre la réactivation.',
    'the_ceiling_on_this_app_s_access_narrowing_it_takes_eff_5f2865bc' => 'La limite maximale d’accès de cette application. Une restriction prend effet au prochain jeton. Si un appareil ou un agent demande une portée que vous retirez, la demande est refusée au lieu d’accorder silencieusement moins de droits.',
    'the_destination_refused_the_settings_a_missing_bucket_a_27207d67' => 'La destination a refusé les paramètres, par exemple à cause d’un bucket absent ou d’une région ou d’un site incorrect. Rien n’est livré avant correction. Les entrées restent en attente et ne sont pas supprimées.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Les domaines de messagerie de cette organisation, chacun vérifié par un enregistrement DNS TXT. Une fois un domaine vérifié, vous pouvez imposer la redirection de toutes les personnes ayant une adresse sur ce domaine vers votre connexion SSO d’entreprise, à la place du mot de passe. Vérifiez donc tous les domaines utilisés avant de vous appuyer sur le SSO.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Les clés que votre code utilise pour appeler Cbox ID, avec un onglet par type. Une clé secrète de gestion permet à votre backend de gérer les organisations, membres, invitations, rôles et applications d’un environnement. Une clé d\'organisation appelle son API avec un rôle intégré. Une clé publiable s’utilise dans une application navigateur et ne fonctionne que depuis les origines autorisées. Les clés secrètes et d\'organisation ne sont affichées qu’une fois. Copiez-les à leur création et révoquez-les immédiatement en cas de fuite.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Le sens inverse : Cbox ID transmet vos utilisateurs aux autres produits SaaS de votre entreprise via leurs points de terminaison SCIM. Vous gérez les arrivées et les départs au même endroit, au lieu d’utiliser un panneau d’administration par fournisseur.',
    'the_name_of_your_organization_which_your_projects_envir_fde906b5' => 'Le nom de votre organisation, qui regroupe vos projets, environnements et équipe et qui apparaît partout dans la console. Supprimer une organisation arrête tous ses environnements de connexion. Il faut donc le demander à l’assistance ; aucun bouton ne permet de le faire.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Les règles de mot de passe, le verrouillage de compte et les exigences de double authentification et de SSO à chaque connexion. À l’échelle de l’environnement, ces paramètres définissent aussi les clés d’accès, les liens de connexion et la durée des sessions. L’environnement fixe une base héritée par chaque organisation. Celle-ci peut renforcer les règles de mot de passe et de double authentification, jamais les assouplir.',
    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'Vos services qui reçoivent des jetons d’accès et les portées appartenant à chacun. Vous décidez à qui attribuer les portées d’une API enregistrée. Personne ne peut simplement les saisir dans une application pour obtenir l’accès à votre API.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'L’environnement entier propose ce fournisseur sur toutes les pages de connexion. Choisissez une organisation pour configurer son propre fournisseur à la place. Celui-ci remplacera alors celui de l’environnement sur la page de connexion de cette organisation.',
    'the_organization_s_own_keys_for_the_organization_api_li_86017b30' => 'Les clés propres à l\'organisation pour son API : lister les projets et environnements, créer des environnements, lister les membres de l’équipe et les inviter. Chaque clé porte un rôle intégré.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Les sessions et jetons de la personne sont révoqués. Ses clés d’accès, seconds facteurs, adhésions, attributions de rôles, jetons API, secrets du coffre, appareils et toutes les copies stockées de ses données sont supprimés. Le compte n’est conservé que sous forme d’un enregistrement pseudonymisé et désactivé. Les applications qui synchronisent les utilisateurs depuis ici reçoivent une demande de suppression. Le journal d’audit conserve l’identifiant opaque, pas le nom ni l’adresse e-mail.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Ces hooks s’exécutent pendant une opération, pas après, et leur réponse en modifie le résultat. Votre point de terminaison peut ajouter des informations à un jeton ou refuser complètement une connexion. Ils interviennent directement dans le déroulement de l’opération : un point de terminaison lent ou défaillant affecte la personne qui tente de se connecter.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'La personne perd immédiatement l’accès à toutes les pages de la plateforme de cette installation. Ses sessions existantes cessent de fonctionner à la prochaine requête. Vous pouvez la réactiver ici.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Cette action est irréversible. Les identifiants, adhésions et données personnelles sont supprimés, et le compte est pseudonymisé. Si cette personne est l’unique propriétaire d’une organisation, transférez d’abord la propriété.',
    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Cette installation ne dispose pas de clés Turnstile (CBOX_ID_TURNSTILE_SITE_KEY), donc aucun contrôle Turnstile ne peut être activé. Une inscription signalée vérifie plutôt son adresse e-mail.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Ce point de terminaison appartient à l’environnement et s’exécute pour chacune de ses organisations. Il apparaît ici parce qu’il intervient lors de vos connexions. Votre opérateur le gère.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Cet environnement propose un serveur MCP en plus de son API REST. Connectez-y un agent avec une clé de gestion : il ne pourra effectuer que les actions autorisées par ses portées, avec les mêmes contrôles, approbations et journal d’audit que la console.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Cet environnement propose un serveur MCP, l’interface standard d’appel d’outils pour les assistants IA, en plus de son API REST. Saisissez l’adresse et une clé de gestion dans Claude Code, Cursor ou un autre client MCP. L’agent ne pourra effectuer que les actions autorisées par les portées de la clé, avec les mêmes contrôles et journal d’audit que la console.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Cet utilisateur ne peut plus se connecter à aucune application de cet environnement. Ses sessions existantes cessent de fonctionner à la prochaine requête. Ses données sont conservées et vous pouvez le réactiver à tout moment.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Cet utilisateur possède ou administre une organisation. Il n’est pas possible d’agir sous l’identité de ces comptes, car cela pourrait donner à une autre personne un contrôle durable sur l’organisation.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Actuellement, les utilisateurs sont ajoutés et retirés manuellement ici. Connectez l’annuaire que votre entreprise utilise déjà pour automatiser les deux opérations, y compris les suppressions que l’on oublie facilement.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Tant qu’une API n’est pas enregistrée, une portée n’est qu’un texte dans une application. Toute personne pouvant modifier l’application peut lui attribuer n’importe quelle portée. Enregistrez les API appelées par vos applications pour que leurs portées aient un propriétaire.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Les domaines vérifiés dirigent les utilisateurs vers votre propre fournisseur d’identité. Cette fonction est incluse dans l’offre Enterprise. Contactez votre équipe commerciale pour l’activer pour cette organisation.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Vérifier un domaine que vous possédez, par exemple acme.com, permet à Cbox ID de reconnaître vos utilisateurs par leur adresse e-mail et de les diriger vers votre fournisseur. Personne n’a ainsi besoin de choisir le bon bouton de connexion.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Les webhooks, notifications de déconnexion aux applications connectées, récupérations de mises à jour de rôles et e-mails en attente sont traités en arrière-plan par les workers de file d’attente, sans faire patienter l’utilisateur. Si aucun worker ne fonctionne, rien de tout cela n’est traité alors que le reste de la console paraît normal. Cette page permet de repérer le problème.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Les actions pour lesquelles les agents de cet environnement attendent une approbation. Si sa clé l’exige, l’agent s’arrête et demande à la personne qui l’a créée. Elle peut répondre sur son téléphone ou ici. Les responsables de l’environnement peuvent refuser les demandes suspectes. En dessous figurent les demandes d’applications souhaitant agir au nom d’un utilisateur, que chaque utilisateur approuve lui-même.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Ce qu’une application peut être autorisée à faire sur cette API. Vos propres applications peuvent détenir toutes ces portées. Celles enregistrées par une organisation ne peuvent détenir que les portées ouvertes aux organisations.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Les actions pour lesquelles les logiciels de cet environnement attendent une approbation. Un agent dont la clé l’exige s’arrête et demande à la personne qui l’a créée. Répondez ici ou sur votre téléphone.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'La clé demandée par votre code et contenue dans le champ feature_flags. Lettres minuscules et chiffres, séparés éventuellement par - _ ou . Elle ne pourra pas être modifiée ensuite.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Lorsqu’une application ou un agent IA a besoin de votre accord pour agir en votre nom, il ne peut pas toujours vous le demander sur l’écran utilisé. La demande apparaît donc ici. N’approuvez que celles que vous avez initiées et vérifiez que le code correspond à celui affiché sur l’appareil demandeur.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Lorsque TOUTES les conditions sont remplies, Radar exécute l’action de cette règle et n’évalue aucune règle suivante. Ces règles sont évaluées après les listes d’autorisation et de blocage et avant les règles intégrées.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'La destination vers laquelle Cbox ID dirige les utilisateurs après leur déconnexion de cette application. L’URI demandée doit figurer ici à l’identique, y compris la barre oblique finale éventuelle. Sinon, la personne reste sur la page de déconnexion de Cbox ID. Laissez vide si l’application ne demande jamais de redirection de retour.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Vos connexions actives, ce qui peut agir en votre nom et les événements de votre compte. Si vous ne reconnaissez pas une session, déconnectez-la et changez votre mot de passe.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Pendant la migration depuis un autre système, votre application peut déclarer son ancien point de connexion dans son manifeste, à côté des rôles. Il apparaît ici pour approbation avant toute utilisation.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Pendant la migration depuis un autre système, une application peut demander la vérification de l’adresse e-mail et du mot de passe des personnes encore absentes de Cbox ID auprès de son ancien point de connexion. Testez-le avant de l’approuver. Toute personne qu’il accepte est créée ici et n’y est plus jamais redirigée. En revanche, s’il est indisponible, les personnes pas encore migrées ne peuvent pas se connecter.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Sans rôles, toutes les personnes connectées reçoivent les droits que l’application accorde à un utilisateur ordinaire. Les rôles permettent de définir une fois qui est, par exemple, éditeur ou membre de l’assistance, et de faire respecter cette répartition par les applications connectées.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Créez une règle pour autoriser, demander une vérification supplémentaire ou bloquer selon ce que vous savez de vos utilisateurs. Par exemple, exigez une vérification hors de vos pays d’activité ou exemptez le réseau de vos bureaux des règles de fréquence de connexion.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Vous agissez sous l’identité de cette personne, dans sa session et avec ses droits. L’accès est limité à 30 minutes et à la lecture seule là où la console peut l’imposer. Chaque requête est enregistrée sous votre nom.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Vous perdez l’accès immédiatement. En tant que propriétaire, vous ne pouvez quitter l’organisation que lorsqu’une autre personne en est propriétaire. Transférez d’abord la propriété ou supprimez l’organisation dans Paramètres.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Le modèle d’accès propre à votre application : types de ressources comme les documents et dossiers, relations comme propriétaire, éditeur et lecteur, et leur héritage. Les lecteurs d’un dossier peuvent par exemple lire tous ses documents. L’application enregistre les relations des personnes aux ressources et demande à chaque requête : « cet utilisateur peut-il modifier ce document ? ». Le schéma détermine la réponse.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Le modèle d’accès propre à votre application : types de ressources, relations de chaque type et règles d’héritage. Votre application écrit des tuples — qui est lié à quoi — et vérifie les autorisations à chaque requête.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Votre application envoie ces événements à raison d’un appel par lot. Chaque événement indique l’organisation dans laquelle il s’est produit. Ils apparaissent ici et chez les administrateurs de cette organisation dès leur réception.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'L’identité visuelle par défaut de votre environnement : apparence, logo et favicon de la connexion hébergée, ainsi que le nom et l’expéditeur affichés aux utilisateurs. Chaque organisation en hérite, sauf si elle définit la sienne.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Votre fournisseur d’identité crée, met à jour et désactive automatiquement les personnes ici via le standard SCIM. Une arrivée ou un départ enregistré dans votre système RH est répercuté dans vos applications en quelques secondes, sans ticket ni compte oublié — ce qui est essentiel lors d’un départ.',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Vos propres méthodes de connexion et sessions actives. Une clé d’accès offre la meilleure protection et l’utilisation la plus rapide : votre appareil la déverrouille par empreinte digitale ou reconnaissance faciale, sans mot de passe à voler par hameçonnage.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Votre récepteur conserve le même secret. Un secret hexadécimal de 64 caractères devient whsec_ suivi de l’encodage base64 de cette chaîne — "whsec_" + base64(secret). Un secret commençant déjà par whsec_ est utilisé tel quel.',
    '_groups_part1_39d243e0' => '{
  "groups": [":part1"]
}',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => ':part1 tâches à effectuer, à peu près dans cet ordre. Chaque tâche est cochée automatiquement dès qu’elle est réellement terminée. Rien n’est à marquer comme terminé manuellement.',
    '_sub_the_person_s_id_org_the_organization_they_are_acti_2e2ddc7f' => '{
  "sub": "l’identifiant de la personne",
  "org": "l’organisation pour laquelle elle agit",
  "roles": [":part1"],
  "permissions": [:part2]
}',
    'an_api_key_organization_settings_api_keys_not_an_applic_916c023d' => 'Une clé API (Paramètres de l’organisation › Clés API), pas une clé d’application. Elle est stockée sous forme chiffrée et ne sera plus affichée.:part1',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Comment les gens se connectent à :part1. Ceux-ci commencent par les valeurs par défaut de votre environnement ; tout ce que vous changez ici ne peut que les rendre plus stricts.',
    'its_members_are_signed_out_and_all_part1_it_owns_stop_s_80b419eb' => 'Ses membres sont déconnectés et tous les :part1 qu\'il possède cessent de fournir l\'authentification à la demande suivante. Vous pouvez le réactiver ici.',
    'its_part1_are_signed_out_and_all_part2_it_owns_stop_ser_c1a0c179' => 'Ses :part1 sont déconnectés et tous les :part2 qu\'il possède cessent de fournir l\'authentification à la demande suivante. Vous pouvez le réactiver ici.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Ses :part1 ne peuvent plus se connecter à cette organisation, et les applications qui s’appuient sur elle ne peuvent plus les authentifier. Les sous-organisations ne sont pas suspendues avec elle. Vous pouvez la réactiver ici.',
    'minutes_at_most_part1_empty_uses_the_deployment_s_part2_2c261db9' => 'Minutes, au maximum :part1. Empty utilise le :part2 du déploiement. Le raccourcir met également fin aux sessions plus longues déjà en cours.',
    'only_if_your_app_needs_more_from_part1_than_sign_in_doe_fc539001' => 'Uniquement si votre application a besoin de plus de :part1 que la connexion, séparés par des espaces. Les propres étendues de connexion sont toujours demandées.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Collez l\'intégralité du fichier de clé JSON d\'un compte de service disposant de rôles/storage.objectCreator sur le compartiment. Stocké crypté et jamais affiché à nouveau.:part1',
    'sandbox_environments_allow_localhost_urls_and_never_sen_299fef2d' => 'Les environnements Sandbox autorisent les URL d\'hôte local et n\'envoient jamais de véritables e-mails. :part1 restant sur le plan de ce projet.',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Connectez-vous à l\'une de vos applications en tant que :part1 pour voir ce qu\'elles voient. L\'application est informée qu\'il s\'agit de vous, et le journal d\'audit de l\'organisation enregistre qui, quand et pourquoi.',
    'the_app_whose_declared_roles_and_permissions_tokens_for_f9092feb' => 'Application dont les rôles et autorisations déclarés pour ce API sont portés. Seules les applications appartenant à :part1 peuvent être choisies.',
    'what_part1_s_sign_in_page_offers_providers_from_the_env_efc01f8e' => 'Ce que propose la page de connexion de :part1. Les fournisseurs de l\'environnement sont hérités ; cette organisation peut en désactiver un ou en créer un à sa place.',
    'when_an_agent_s_key_needs_approval_for_an_action_the_re_56c5e366' => 'Lorsque la clé d\'un agent nécessite une approbation pour une action, la demande apparaît ici et sur le téléphone de la personne qui a créé la clé. Il attend jusqu\'à :part1.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Quelles méthodes disponibles dans :part1 en plus d\'un mot de passe et combien de temps dure une connexion. Ce sont les mêmes pour chaque organisation qui en fait partie.',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 Le champ :part2 est différent : il indique ce que :part3 :part4 était autorisé à demander, et non ce que cette :part5 peut faire.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Ils ne servent pas à se connecter à cette console : les administrateurs passent par Cbox ID sur :part2, avec les méthodes de connexion qui y sont proposées.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Cochez la portée :part2 :part3 lors de l’enregistrement de l’application. Le jeton d’identité contiendra les mêmes noms de rôles dans le champ :part4, celui que recherchent Kubernetes, Grafana et Vault. Rien d’autre à créer.',
    '_part1_you_are_impersonating_part2_part3_for_support_ev_aaad4d39' => ':part1 Vous agissez en tant que :part2 :part3 pour l’assistance. Toutes vos actions sont journalisées. :part4 :part5 :part6',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Une clé de gestion agit uniquement dans son propre environnement. Exportez le modèle de cette application (GET /apps/{id}/blueprint), puis enregistrez-le avec la clé de l’autre environnement (POST /apps avec `blueprint`).',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Une clé de gestion pour un seul agent. Elle n’autorise que les actions permises par ses portées. Les actions que vous choisissez attendent votre approbation, sur votre téléphone ou sur :part1.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'Une page sur :part1. Laissez vide pour ouvrir la console, avec :part2 indiqué sur l’invitation.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => 'Un :part1 est le fournisseur d’identité d’un produit. Il contient des :part2 :part3 isolés, en production et en bac à sable, chacun avec ses propres utilisateurs, clés et connexion, et dispose de son propre abonnement.',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'Une permission détermine ce qu’une :part1 peut faire après connexion. Ce qu’une :part2 peut demander est une portée, définie lors de son enregistrement sous :part3 :part4.',
    'an_organization_key_reaches_the_organization_itself_pro_0257779c' => 'Une clé d\'organisation accède à l’espace lui-même : projets, environnements, équipe et clés. Elle n’accède pas au contenu d’un environnement. Créez-en une sous :part1 :part2 :part3 à la racine de la plateforme.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Les jetons d’accès de cette application désignent :part1 comme destinataire :part2. Cette API ne doit accepter un jeton que si celui-ci la désigne.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Les jetons d’accès de cette application désignent l’émetteur de cet environnement, :part1 :part2, comme destinataire. Cela change lorsque l’application possède une portée de l’une de vos API enregistrées.',
    'add_a_txt_record_at_part1_part2_with_the_value_below_th_455edc17' => 'Ajoutez un enregistrement TXT sur :part1 :part2 avec la valeur ci-dessous, puis cliquez sur Vérifier. La propagation des modifications DNS peut prendre quelques minutes.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'Une application enregistre son catalogue via le SDK. :part1 :part2 Vous pouvez créer le rôle maintenant et le composer lorsque les clés seront disponibles.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Applications qui font confiance à cet environnement comme fournisseur d’identité SAML. Pour permettre une connexion avec un compte existant ailleurs, utilisez :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Les approbations couvrent les actions de l’API de gestion. Ces portées sont utilisées par des points de terminaison qui ne sont pas encore des actions ; ils s’exécutent donc sans demander d’approbation : :part1 :part2.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Les applications dirigent les utilisateurs vers l’inscription avec :part1 et demandent aux utilisateurs connectés de créer une organisation avec :part2. Ces deux possibilités ne sont proposées que lorsque cette option est activée.',
    'asked_exactly_as_your_app_asks_it_part1_through_every_i_42253b49' => 'La demande est formulée exactement comme dans votre application (:part1), en suivant tous les héritages définis par le schéma.',
    'auth_settings_differ' => ':count paramètre diffère de votre environnement.|:count paramètres diffèrent de votre environnement.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_df000287' => 'Connectez-vous une seule fois à la racine de la plateforme plutôt que dans chaque environnement. En votre nom, la connexion accède à votre organisation, à tous ses environnements que vous administrez et à votre compte. Un outil d’environnement reçoit un argument :part1 :part2, et l’API REST un en-tête :part3, pour désigner la cible. Elle peut faire ce que vous pouvez faire, dans les limites de votre autorisation, et toute action critique attend votre approbation sur votre appareil.',
    'each_new_account_creates_its_own_organization_and_owns_3528fda3' => 'Chaque nouveau compte crée et possède sa propre organisation. Les applications peuvent aussi demander à un utilisateur connecté d’en créer une avec :part1 :part2.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Chaque organisation leur attribue un :part1, qui détermine ce qu’ils peuvent y administrer, ainsi qu’un nombre quelconque de :part2, qui déterminent ce qu’ils peuvent faire dans ses applications.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'L’environnement « :part1 » a été créé. Ajoutez :part2 dans ses paramètres de domaine pour le vérifier par DNS. Un domaine non vérifié ne peut pas être son émetteur.',
    'environments_nest_under_a_project_and_a_project_under_a_a7f5aa8e' => 'Les environnements appartiennent à un projet, et les projets à un :part1 :part2 :part3. Commencez par là pour voir tout une organisation. Deux types de lignes n’ont jamais d\'organisation : :part4 est l’environnement de cette installation, où résident les opérateurs et les utilisateurs des organisations ; un environnement :part5 :part6 n’a pas de projet, n’est donc pas facturé et n’est accessible depuis aucune organisation. Aucun des deux cas n’est une erreur à corriger ici, et cet écran ne les réaffecte pas.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Toutes les méthodes de connexion à :part1, leur état et l’endroit où les modifier. Les organisations peuvent renforcer ces exigences : :part2 :part3.',
    'every_organization_environment_and_operator_on_part1_a__f425b7e6' => 'Tous les organisations, environnements et opérateurs sur :part1. Une suspension, un nouvel environnement ou un changement d’opérateur ici s’applique à l’ensemble.',
    'feature_flag_part1_created_it_is_off_for_everyone_until_32603be3' => 'L’indicateur de fonctionnalité « :part1 » a été créé. Il est désactivé pour tous jusqu’à ce qu’une règle ci-dessous ou sa valeur par défaut l’active.',
    'framework_3cf574caed49' => 'Les portées :value1 appartiennent à une API enregistrée à laquelle ce client ne peut pas accéder. Un client appartenant à une organisation peut détenir les portées de ses propres API et celles des API de l’environnement que les organisations sont autorisées à demander.',
    'framework_43fd205dea6a' => 'La portée [:key] appartient déjà à une autre API de cet environnement. Les clés de portée sont uniques par environnement, car une demande de jeton désigne une portée uniquement par sa clé.',
    'framework_47867973811e' => 'La synchronisation de l’annuaire avec :provider a échoué : :request a subi une limitation de débit (HTTP :status). Nombre de tentatives : :attempt.',
    'framework_5eb368b0fb37' => 'Workday : l’URL du rapport doit être son adresse de service web : …/ccx/service/customreport2/{tenant}/{owner}/{report}.',
    'framework_632573ec7b49' => 'L’application [:clientId] doit avoir le même propriétaire que l’API dont elle contrôle l’accès. Sinon, cette liaison placerait les rôles et permissions d’un propriétaire dans les jetons d’un autre.',
    'framework_87da9891b0ad' => 'La synchronisation de l’annuaire avec :provider a échoué : :request était indisponible (HTTP :status) après :attempt tentatives.',
    'framework_98eb4683e38b' => 'La synchronisation de l’annuaire avec :provider a échoué : :request a échoué (HTTP :status) : ressource introuvable. Vérifiez le compte, le sous-domaine ou l’adresse du rapport.',
    'framework_a934fd6a0c26' => '[:origin] utilise http : la clé et toutes les opérations effectuées avec elle seraient transmises en clair sur le réseau. Utilisez https ou une adresse locale comme http://localhost:3000 pendant le développement.',
    'framework_b63785ee57fb' => 'La synchronisation de l’annuaire avec :provider a échoué : :request a échoué (HTTP :status) : les identifiants ne permettent pas de lire les employés.',
    'framework_e5ca82ab9dff' => 'La synchronisation de l’annuaire avec :provider a échoué : :request a échoué (HTTP :status) : les identifiants ont été refusés.',
    'framework_fc1964a8e8c4' => 'C’est le dernier secret actif du client [:clientId]. Renouvelez-le pour le remplacer : sa révocation empêcherait le client de s’authentifier.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Si ce point de terminaison est :part1, les utilisateurs qui n’ont pas migré ne peuvent pas se connecter. Ceux qui ont déjà migré ne sont pas affectés.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'Dans l’ordre présenté aux utilisateurs. Désactiver ici une méthode de l’environnement retire uniquement son bouton de cette page, sans empêcher son utilisation ailleurs. Pour faire de votre fournisseur d’identité l’unique méthode de connexion, imposez le SSO sur :part1 :part2.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Les clés commencent par ce préfixe, ce qui permet d’associer à cette application une clé trouvée dans un journal : :part1 :part2. De 2 à 16 lettres minuscules ou chiffres, suivis de :part3 ou :part4 :part5, uniques dans cet environnement. Définir un préfixe active les clés. L’effacer empêche d’en créer de nouvelles ; celles déjà créées restent valides jusqu’à leur révocation.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Lister les indicateurs de fonctionnalité avec leurs règles de ciblage et évaluer chaque indicateur pour un utilisateur d’une organisation. C’est la demande effectuée par le backend d’une application lorsqu’il ne dispose pas d’un jeton.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Lister les annuaires (SCIM, Google Workspace, Microsoft Entra) qui synchronisent les utilisateurs, leurs groupes et les erreurs de synchronisation, sans jamais exposer de jeton bearer ni d’identifiants de fournisseur.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Lister les connexions SAML et OIDC utilisées par les organisations et les domaines de messagerie qui y dirigent les utilisateurs, sans jamais exposer de certificat, de secret client ni de clé de signature.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Lister les fournisseurs tiers auxquels les utilisateurs peuvent connecter leurs comptes, les applications autorisées à utiliser temporairement leurs jetons et les personnes connectées, sans jamais exposer de secret client ni de jeton.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Créer et révoquer des liens à usage unique vers le portail d’administration. Ils permettent à l’administrateur informatique d’une organisation de configurer le SSO, les domaines ou la synchronisation d’annuaire sans compte. Un nouveau lien n’est affiché qu’une seule fois.',
    'no_roles_to_map_onto_yet_define_one_under_part1_part2_o_9b9aba76' => 'Aucun rôle à associer pour le moment. Définissez-en un sous :part1 :part2, ou laissez une application déclarer les siens.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_d0240315' => 'Personne dans cette organisation n’a créé de clé pour l’une de ses applications. Les utilisateurs créent leurs propres clés sous Mon compte, pour une application ayant activé les clés API des membres dans ses paramètres : :part1.',
    'nobody_is_signed_in_to_an_app_as_one_of_its_people_star_a41ae388' => 'Personne n’est connecté à une application en tant que l’un de ses utilisateurs. Démarrez une telle session depuis la fiche d’un utilisateur sous :part1 :part2.',
    'only_the_console_can_give_an_app_part1_not_a_management_e9037160' => 'Seule la console peut accorder :part1 à une application. Ni une clé de gestion ni un agent agissant pour vous ne le peuvent. Accordez cet accès dans la console, sur la page des portées de l’application.',
    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Seules les actions que vous pouvez vous-même effectuer dans :part1 sont proposées. Si vous perdez une permission par la suite, la clé la perd aussi.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Ajoute les clés des indicateurs de fonctionnalité activés pour la personne dans l’organisation à laquelle elle s’est connectée sous forme de champ `feature_flags` dans le jeton d’accès, le jeton d’identité et UserInfo.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Ajoute les RÔLES de la personne au jeton d’identité sous le nom `groups`, attendu par Kubernetes, Grafana, Vault et de nombreuses applications SaaS plus anciennes. Cette console n’a pas d’objet appelé groupe. Créez un rôle portant le nom attendu par l’application ; il sera inclus dans ce champ.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Lire le mode de Radar, ses règles intégrées et personnalisées, ses listes d’autorisation et de blocage et la vue des décisions : pourquoi une connexion ou inscription a été autorisée, soumise à une vérification supplémentaire ou bloquée. Aucune adresse IP ou e-mail provenant d’une décision n’est exposée.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Lire les événements d’audit envoyés par votre application et leurs exportations, vérifier la chaîne d’événements d’une organisation et consulter les schémas et règles de conservation applicables.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Lire le schéma d’autorisation et ses tuples, puis effectuer des contrôles de permission et des requêtes de liste, par exemple « cet utilisateur peut-il modifier ce document ? » ou « quels documents peut-il voir ? ». Uniquement les droits nécessaires au backend d’une application pour contrôler l’accès.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Remplacer le schéma d’autorisation : les types de ressources et le calcul de chaque relation. Cela modifie immédiatement la réponse à tous les contrôles de cet environnement.',
    'roles_held_across_the_whole_environment_in_every_organi_eb64cef7' => 'Rôles détenus dans tout l’environnement, dans chaque organisation, même pour les personnes qui n’appartiennent à aucune. Les organisations ne les voient jamais. :part1 :part2',
    'sandbox_environment_for_testing_only_this_is_part1_your_4efdd306' => 'Environnement de test uniquement. Ce n’est :part1 votre connexion de production, et aucun véritable e-mail n’est envoyé.',
    'scope_part1_removed_apps_that_held_it_keep_it_as_a_type_7572a80d' => 'La portée « :part1 » a été supprimée. Les applications qui la détenaient la conservent comme portée libre, qui ne donne plus accès à cette API.',
    'showing_the_first_part1_search_to_reach_the_rest_anythi_57d8cba9' => 'Affichage des :part1 premiers éléments. Recherchez pour trouver les autres. Les éléments déjà cochés restent dans la liste.',
    'sms_allowed_country_count' => 'Accepté comme second facteur dans :count pays.|Accepté comme second facteur dans :count pays.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Les personnes qui :part1 ne sont jamais transmises : leur mot de passe est celui de Cbox ID, et l’ancien système n’a aucune autorité dessus.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Lorsqu’une personne se connecte et est :part1, son adresse e-mail et son mot de passe sont envoyés à ce point de terminaison. S’il les accepte, son compte est créé ici et ses données ne lui sont plus jamais transmises.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Stocker, renouveler et révoquer les identifiants de services externes, et accorder ou retirer à une application le droit de les utiliser temporairement. Cela ne concerne pas les portées vault.manage / vault.lease présentes dans le jeton propre à l’application.',
    'streamable_http_every_request_carries_part1_part2_a_man_6348600d' => 'Streamable HTTP. Chaque requête contient :part1 :part2, une clé de gestion de cet environnement.',
    'stuck_on_one_of_these_every_page_in_the_console_has_a_p_2aa4622e' => 'Besoin d’aide sur l’un de ces points ? Chaque page de la console comporte un :part1 :part2 :part3 à côté du titre, avec une explication courte et un lien vers le guide complet.',
    'suspension_is_the_only_lever_here_and_it_is_reversible__9f87c506' => 'Seule la suspension peut être modifiée ici, et elle est réversible. Rien sur cette page ne supprime une organisation ni ne purge ses données. L’installation contient aussi des environnements sans organisation : la racine de la plateforme et les éventuels environnements non rattachés. Ils sont clairement identifiés sous :part1 :part2.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Cette page ne modifie que la suspension, qui peut être levée. Sélectionner et ouvrir un environnement change uniquement la vue de la console, sans modifier aucun des environnements.',
    'text_message_codes_to_part1_stop_working_their_authenti_81d0cd27' => 'Les codes SMS envoyés à :part1 ne fonctionneront plus. L’application d’authentification, les clés d’accès et les codes de récupération ne sont pas affectés. Si ce numéro était le seul second facteur, le compte ne sera protégé que par son mot de passe jusqu’à une nouvelle configuration.',
    'that_certificate_has_already_expired_part1_download_the_9adb4bed' => 'Ce certificat a déjà expiré (:part1). Téléchargez le certificat actuel auprès de votre fournisseur d’identité.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Ce favicon ne peut pas être utilisé. Envoyez l’image elle-même sous forme d’URI data: encodée en base64 (data:image/png;base64,…). Les URL d’images externes ne sont pas acceptées : chaque visiteur charge l’image de la page de connexion, ce qui communiquerait des informations sur les visiteurs au serveur externe.',
    'that_is_a_lot_of_emails_try_again_in_part1_seconds_or_c_1e69af47' => 'Beaucoup d’e-mails ont été demandés. Réessayez dans :part1 secondes ou consultez votre dossier de courriers indésirables en attendant.',
    'that_is_everything_on_the_list_from_here_the_console_is_d3be406f' => 'Tous les éléments de la liste sont terminés. Vous reviendrez désormais surtout dans la console selon vos besoins. Deux sections méritent une consultation régulière : :part1 :part2 :part3 et :part4 :part5 :part6.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Ce logo ne peut pas être utilisé. Envoyez l’image elle-même sous forme d’URI data: encodée en base64 (data:image/png;base64,…). Les URL d’images externes ne sont pas acceptées : chaque visiteur charge l’image de la page de connexion, ce qui communiquerait des informations sur les visiteurs au serveur externe.',
    'the_email_domains_your_organizations_have_claimed_a_ver_97773852' => 'Les domaines de messagerie revendiqués par vos organisations. Un domaine vérifié dirige toutes les personnes ayant une adresse sur ce domaine vers la connexion de l’organisation : :part1 :part2. Chaque domaine est vérifié sur la page de son organisation.',
    'the_platform_s_own_environment_on_part1_how_every_organ_acd123ad' => 'L’environnement propre à la plateforme sur :part1 : il permet à tous les propriétaires d\'organisations et opérateurs de se connecter à Cbox ID, ainsi qu’à toutes les consoles d’environnement. Toute modification s’applique à l’ensemble de ces connexions.',
    'the_role_part1_cannot_be_held_in_this_organization_it_b_6fdeacd4' => 'Le rôle [:part1] ne peut pas être attribué dans cette organisation : il appartient à une autre organisation ou à une application que celle-ci ne peut pas utiliser.',
    'there_is_no_client_secret_to_paste_part1_expects_a_sign_574fe375' => 'Il n’y a pas de secret client à coller. :part1 attend une assertion signée, que nous créons avec la clé ci-dessus pour chaque connexion et renouvelons bien avant son expiration.',
    'there_is_no_role_to_grant_yet_define_one_on_the_part1_p_ffe056a6' => 'Aucun rôle ne peut encore être attribué. Définissez-en un sur la page :part1 :part2 :part3, ou laissez une application déclarer les siens dans son manifeste.',
    'these_are_the_buttons_on_part1_how_every_organization_o_ca549807' => 'Voici les boutons de :part1 utilisés par les propriétaires d\'organisations et les opérateurs pour se connecter à Cbox ID, puis aux consoles de tous les environnements, dont les administrateurs utilisent des comptes Cbox ID. Enregistrez auprès de chaque fournisseur l’URI de redirection indiquée. Elle se trouve sous :part2 :part3.',
    'these_buttons_are_for_the_people_who_sign_in_to_your_ap_580f5efd' => 'Ces boutons sont destinés aux utilisateurs qui se connectent à vos applications, sur les pages de connexion de :part1 :part2. :part3',
    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'Cette personne devient propriétaire de :part1 et vous devenez administrateur. Seul le nouveau propriétaire peut vous rendre la propriété.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Cette application possède des portées de plusieurs API : :part1 :part2. Un jeton ne vise qu’une API à la fois ; l’application indique donc celle souhaitée avec le paramètre :part3. Une demande portant sur les portées de deux API à la fois est refusée.',
